/**
 * Comparing ONB Accuracy
 *
 * ===
 * References:
 *   - Building an Orthonormal Basis from a 3D Unit Vector Without Normalization
 *     Frisvad, Jeppe Revall
 *     https://backend.orbit.dtu.dk/ws/portalfiles/portal/126824972/onb_frisvad_jgt2012_v2.pdf
 *
 *   - Combing Hair and Sampling Directions
 *     Jeppe Revall Frisvad
 *     https://people.compute.dtu.dk/jerf/code/hairy/HairAndDirections.pdf
 *
 *   - Improved accuracy when building an orthonormal basis
 *     Nelson Max
 *     https://jcgt.org/published/0006/01/02/paper.pdf
 *
 *   - Building an Orthonormal Basis, Revisited
 *     Tom Duff, James Burgess, Per Christensen, Christophe Hery, Andrew Kensler, Max Liani, and Ryusuke Villemin
 *     https://graphics.pixar.com/library/OrthonormalB/paper.pdf
 */

/**
 * 0: upper hemisphere
 * 1: lower hemisphere
 */
#define HEMISPHERE 1

/**
 * 0: frisvad vs max
 * 1: frisvad vs pixar
 * 2: max vs pixar
 */
#define COMPARISON_MODE 0

/**
 * If the area around the singularity is hard to see, set a larger value like 2
 */
const float CIRCLE_RADIUS = 1.;
const vec2 CIRCLE_CENTER = vec2(0.);

void onb_common(in vec3 n, out vec3 b1, out vec3 b2, in float thres){
    if(n.z < thres){ // Handle the singularity
        b1 = vec3( 0., -1., 0.);
        b2 = vec3(-1.,  0., 0.);
        return;
    }
    float a = 1. / (1. + n.z);
    float b = - n.x * n.y * a;
    b1 = vec3(1. - n.x * n.x * a, b, -n.x);
    b2 = vec3(b, 1. - n.y * n.y * a, -n.y);
}

void onb_frisvad(in vec3 n, out vec3 b1, out vec3 b2){
    onb_common(n, b1, b2, -0.9999999);
}

void onb_max(in vec3 n, out vec3 b1, out vec3 b2){
    onb_common(n, b1, b2, -0.99998796);
}

void onb_pixar(in vec3 n, out vec3 b1, out vec3 b2){
    float s = n.z >= 0. ? 1. : -1.;
    float a = -1. / (s + n.z);
    float b = n.x * n.y * a;

    b1 = vec3(1. + s * n.x * n.x * a, s * b, -s * n.x);
    b2 = vec3(b, s + n.y * n.y * a, -n.y);
}

float rmse(in vec3 b1, in vec3 b2, in vec3 n){
    float err, sq_err = 0.;

    err = length(n) - 1.;
    sq_err += err * err;
    err = length(b1) - 1.;
    sq_err += err * err;
    err = length(b2) - 1.;
    sq_err += err * err;

    err = dot(n, b1);
    sq_err += err * err;
    err = dot(n, b2);
    sq_err += err * err;
    err = dot(b1, b2);
    sq_err += err * err;

    return sqrt(sq_err / 6.);
}

float normalize_error_value(float err){
    return clamp((log(err) - log(1e-9)) / (log(1e-1) - log(1e-9)), 0., 1.);
}

vec3 colormap(float t){
    const vec3 c0 = vec3(0.0, 0.0, 1.0);
    const vec3 c1 = vec3(0.0, 1.0, 1.0);
    const vec3 c2 = vec3(1.0, 1.0, 0.0);
    const vec3 c3 = vec3(1.0, 0.0, 0.0);
    const vec3 c4 = vec3(1.0, 1.0, 1.0);

    if(t < 0.25)
        return mix(c0, c1, t * 4.);
    if(t < 0.50)
        return mix(c1, c2, (t - 0.25) * 4.);
    if(t < 0.75)
        return mix(c2, c3, (t - 0.50) * 4.);

    return mix(c3, c4, (t - 0.75) * 4.);
}

vec3 error(in vec2 p, in vec2 c, in float r, in int id){
    vec3 n, b1, b2;

    n.xy = (p - c) / r;
    n.z = sqrt(1. - n.x * n.x - n.y * n.y);
#if (HEMISPHERE != 0)
    n.z = -n.z;
#endif

#if (COMPARISON_MODE == 0)
    if(id == 0) onb_frisvad(n, b1, b2);
    else onb_max(n, b1, b2);
#elif (COMPARISON_MODE == 1)
    if(id == 0) onb_frisvad(n, b1, b2);
    else onb_pixar(n, b1, b2);
#else
    if(id == 0) onb_max(n, b1, b2);
    else onb_pixar(n, b1, b2);
#endif

    float err = rmse(b1, b2, n);
    float t = normalize_error_value(err);

    return colormap(t);
}

vec3 linear_to_srgb(in vec3 color){
    vec3 lo = 12.92 * color;
    vec3 hi = 1.055 * pow(color, vec3(1./2.4)) - 0.055;

    return mix(hi, lo, lessThanEqual(color, vec3(0.0031308)));
}

void mainImage(out vec4 fragColor, in vec2 fragCoord){
    vec2 uv = fragCoord / iResolution.xy;
    vec3 color;

    if(uv.x < 0.0125){
#if (COMPARISON_MODE == 0)
        color = vec3(1., 0., 0.);
#elif (COMPARISON_MODE == 1)
        color = vec3(0., 1., 0.);
#else
        color = vec3(0., 0., 1.);
#endif
    }else if(uv.x >= 0.95){
        color = colormap(uv.y);
    }else{
        vec2 p = (2. * fragCoord - iResolution.xy) / iResolution.y;

        if(distance(p, CIRCLE_CENTER) < CIRCLE_RADIUS){
            int id = int(step(iMouse.x, fragCoord.x));
            color = error(p, CIRCLE_CENTER, CIRCLE_RADIUS, id);
        }else{
            color = vec3(0.);
        }

        // Separator
        float sep = smoothstep(0., 2., abs(fragCoord.x - iMouse.x));
        color = mix(1. - color, color, mix(sep, 1., step(iMouse.z, 0.)));
    }

    fragColor = vec4(linear_to_srgb(color), 1.);
}
